-- PLAN NRW: Wissensseite „Isolationsmaßnahmen in der Pflege“ ausführlich (02.11.2026)
-- Inhalte aus der Rubrik Isolationsmanagement (window.PL_ISO), Go P. Schenkelberger 02.11.2026.
-- Im Supabase-SQL-Editor ausführen. Überschreibt die bisherige Kurzfassung der Seite /wissen/isolationsmassnahmen.
update public.lerninhalte set
  titel = 'Isolationsmaßnahmen in der Pflege',
  daten = $j${"definition": "Isolationsmanagement umfasst alle Maßnahmen, die verhindern, dass Krankheitserreger von einer infizierten oder besiedelten Person auf andere übertragen werden – oder umgekehrt eine abwehrgeschwächte Person vor Erregern schützen. Die Isolierungsart richtet sich nach dem Übertragungsweg: Kontakt, Tröpfchen oder Luft (aerogen). Basishygiene gilt dabei immer.", "tabelle_titel": "Erreger und Isolierung im Überblick", "tabelle": {"kopf": ["Erreger", "Übertragung", "Schutzausrüstung", "Dauer der Isolierung"], "zeilen": [["Clostridioides difficile (CDI)", "Kontakt (Sporen, fäkal-oral)", "Kittel + Handschuhe bei jedem Kontakt", "Frühestens 48 Stunden nach Ende der Durchfälle (Hygieneplan)"], ["Hepatitis B / C, HIV", "Blut und Körperflüssigkeiten", "Basishygiene: Handschuhe bei Blutkontakt, Schutzbrille bei Spritzgefahr", "–"], ["Herpes zoster (Gürtelrose)", "Lokalisiert: Kontakt mit Bläscheninhalt · Disseminiert: auch aerogen", "Handschuhe bei Kontakt mit Läsionen; bei Disseminierung nur immunes Personal", "Bis alle Bläschen verkrustet sind"], ["Influenza", "Tröpfchen (und Kontakt über Hände/Flächen)", "MNS beim Betreten; bei aerosolbildenden Maßnahmen (z. B. Absaugen, Bronchoskopie) FFP2 nach Hygieneplan; …", "Nach Hygieneplan, meist bis etwa 7 Tage nach Erkrankungsbeginn bzw. bis zur Besserung (bei Abwehrschwäche …"], ["Masern", "Luft (aerogen) – sehr ansteckend", "Nur Personal mit nachgewiesener Immunität (Masernschutz, § 20 IfSG); Atemschutz nach Hygieneplan", "Bis 4 Tage nach Beginn des Hautausschlags"], ["Meningokokken (Meningitis/Sepsis)", "Tröpfchen", "MNS bei engem Kontakt, Kittel/Handschuhe bei Kontakt mit Sekreten", "Bis 24 Stunden nach Beginn der wirksamen Antibiotikatherapie"], ["MRGN – 3MRGN", "Kontakt", "Bei Isolierung Kittel + Handschuhe bei Kontakt", "Nach Hygieneplan (Besiedlung oft lang anhaltend)"], ["MRGN – 4MRGN", "Kontakt", "Kittel + Handschuhe bei Kontakt mit Patient und Umgebung", "Nach Hygieneplan, meist für den gesamten Aufenthalt"], ["MRSA", "Kontakt (bei Besiedlung der Atemwege auch Tröpfchen)", "Kittel + Handschuhe bei Kontakt mit Patient und Umgebung; MNS bei Tätigkeiten mit Spritz- oder Aerosolgefahr (z. B. …", "Nach erfolgreicher Sanierung: Kontrollabstriche frühestens 3 Tage nach Sanierungsende an 3 …"], ["Mumps", "Tröpfchen", "MNS; nicht immunes Personal möglichst nicht einsetzen", "Bis 5 Tage nach Beginn der Ohrspeicheldrüsenschwellung"], ["Noroviren", "Kontakt (fäkal-oral) – beim Erbrechen auch Tröpfchen/Aerosole", "Kittel + Handschuhe; MNS bei Kontakt mit erbrechenden Personen bzw. bei Aerosolgefahr", "Frühestens 48 Stunden nach Ende der Symptome"], ["Pertussis (Keuchhusten)", "Tröpfchen", "MNS", "Bis 5 Tage nach Beginn der Antibiotikatherapie"], ["Röteln", "Tröpfchen", "MNS; nur immunes Personal, keine nicht immunen Schwangeren", "Bis etwa 1 Woche nach Beginn des Ausschlags"], ["Rotaviren", "Kontakt (fäkal-oral)", "Kittel + Handschuhe", "Frühestens 48 Stunden nach Symptomende (Hygieneplan)"], ["RSV", "Tröpfchen und Kontakt (Hände, Flächen)", "MNS, Kittel + Handschuhe bei Kontakt", "Nach Hygieneplan, meist bis zum Ende der Symptome"], ["SARS-CoV-2", "Tröpfchen und Aerosole", "Nach aktuellem Hygieneplan, häufig FFP2; Kittel/Handschuhe bei Kontakt", "Nach Hygieneplan"], ["Skabies (Krätze)", "Kontakt (längerer Hautkontakt); bei Scabies crustosa auch über Wäsche und Flächen", "Langärmeliger Kittel + Handschuhe bei Körperkontakt", "Nach Abschluss der Behandlung nach ärztlicher Vorgabe"], ["Tuberkulose (offene Lungen-TB)", "Luft (aerogen)", "FFP2-Maske (Dichtsitz prüfen); bei besonderen Tätigkeiten (z. B. Bronchoskopie, resistente TB) ggf. FFP3 nach …", "Nur nach ärztlicher Entscheidung (Befunde, Therapieverlauf – in der Regel negative Sputumproben)"], ["VRE", "Kontakt", "Kittel + Handschuhe bei Kontakt", "Nach Hygieneplan"], ["Windpocken (Varizellen)", "Luft (aerogen) und Kontakt", "Nur immunes Personal", "Bis alle Bläschen verkrustet sind (meist 5–7 Tage nach Beginn des Ausschlags)"]]}, "einteilung": "Kontakt: Direkt über Hände und Haut oder indirekt über Flächen, Geräte, Wäsche, Toiletten. Beispiele: MRSA, VRE, MRGN, C. difficile, Noroviren, Rotaviren, Skabies. Schutz: Kittel + Handschuhe bei Kontakt mit Patient oder Umgebung, konsequente Händedesinfektion, patientenbezogene Utensilien.\nTröpfchen: Größere Tröpfchen beim Husten, Niesen, Sprechen. Sie sinken schnell ab – Reichweite meist 1–2 m. Oft zusätzlich Kontakt über Hände und Flächen. Beispiele: Influenza, RSV, Pertussis, Meningokokken, Mumps, Röteln, SARS-CoV-2 (auch Aerosole). Schutz: Medizinische Gesichtsmaske (MNS) beim Betreten bzw. bei engem Kontakt, Abstand, Patient trägt MNS außerhalb des Zimmers.\nLuft (aerogen): Sehr kleine Partikel (Tröpfchenkerne, Aerosole) schweben lange in der Luft und werden über weite Strecken getragen – auch in Nachbarräume. Beispiele: Offene Lungentuberkulose, Masern, Windpocken, disseminierter Herpes zoster. Schutz: Einzelzimmer mit geschlossener Tür, FFP2-Maske (Atemschutz), bei Masern und Windpocken nur immunes Personal.\nBlut & Körperflüssigkeiten: Über Stich- und Schnittverletzungen, Schleimhautkontakt oder nicht intakte Haut. Beispiele: Hepatitis B und C, HIV. Schutz: Keine Isolierung nötig – Basishygiene, Handschuhe, sichere Instrumente, kein Recapping, Hepatitis-B-Impfung.\nSchutzisolierung (Umkehrisolierung): schützt stark abwehrgeschwächte Menschen, z. B. bei schwerer Neutropenie – Einzelzimmer, Händedesinfektion vor jedem Betreten, keine Pflanzen, kein Besuch mit Infektzeichen, diese Person zuerst versorgen.", "material": "Medizinische Gesichtsmaske (MNS, „OP-Maske“) (EN 14683): Schützt vor allem andere vor deinen Tröpfchen und dich vor Spritzern auf Mund und Nase. Sitzt nicht dicht – kein Atemschutz gegen Aerosole. Wann: Tröpfcheninfektionen, Spritzgefahr, Patient außerhalb des Zimmers.\nFFP2-Maske (EN 149): Atemschutz: filtert mindestens 94 % der Partikel, wenn sie dicht sitzt. Ein Bart oder falsch geformter Nasenbügel macht sie undicht. Tragezeiten nach Arbeitsschutz (DGUV) und Hygieneplan beachten. Wann: Aerogene Erreger (z. B. offene Tuberkulose), aerosolbildende Maßnahmen nach Hygieneplan.\nFFP3-Maske (EN 149): Filtert mindestens 99 % der Partikel. Höherer Atemwiderstand. Wann: Nur bei besonderen Tätigkeiten nach Gefährdungsbeurteilung (z. B. Bronchoskopie bei resistenter TB).\nMaske mit Ausatemventil (–): Schützt nur die tragende Person – die Ausatemluft geht ungefiltert nach außen. Wann: Nicht geeignet, wenn andere geschützt werden sollen (z. B. bei Schutzisolierung, im OP).\nSchutzkittel: Langärmelig mit Bündchen, schließt im Rücken; Flüssigkeitsdicht, wenn Durchfeuchtung droht (z. B. Erbrechen, Durchfall, Waschen); Wird patientenbezogen und nur im Zimmer getragen – nicht auf dem Flur; Bei Durchfeuchtung oder sichtbarer Verschmutzung sofort wechseln; Wiederverwendung nur, wenn der Hygieneplan es ausdrücklich regelt (dann Innenseite nach innen, im Zimmer aufhängen).\nHandschuhe: Medizinische Einmalhandschuhe (EN 455); beim Umgang mit Desinfektionsmitteln chemikalienbeständige Handschuhe (EN ISO 374); Erst nach der Händedesinfektion anziehen – Hände müssen trocken sein; Bündchen über die Kittelärmel ziehen; Wechseln zwischen Patienten, von unrein zu rein und bei Beschädigung; Nach dem Ausziehen immer Hände desinfizieren – Handschuhe haben Mikroperforationen; Mit Handschuhen keine Türklinken, Telefone, Kurven oder Kugelschreiber anfassen.", "durchfuehrung": "Schutzausrüstung anlegen: Vorbereiten → Hände desinfizieren → Schutzkittel anziehen → Maske aufsetzen → Schutzbrille aufsetzen → Hände desinfizieren, Handschuhe an. Anlegen: Hände desinfizieren → Kittel → Maske → Brille → Hände desinfizieren → Handschuhe über die Ärmel.\nSchutzausrüstung ablegen: Handschuhe ausziehen → Hände desinfizieren → Kittel ausziehen → Schutzbrille abnehmen → Maske abnehmen → Hände desinfizieren. Ablegen: Handschuhe → Hände desinfizieren → Kittel → Brille → Maske (bei Luftübertragung draußen) → Hände desinfizieren.\nFFP2-Dichtsitz prüfen: Maske mit beiden Händen anfassen, Bänder hinter den Kopf bzw. die Ohren. Nasenbügel mit beiden Zeigefingern an die Nase anmodellieren (nicht kneifen). Maske mit den Händen abdecken und kräftig ausatmen: Es darf keine Luft am Rand entweichen. Kräftig einatmen: Die Maske zieht sich leicht an das Gesicht. Bei Undichtigkeit neu anpassen oder eine andere Größe/ein anderes Modell nehmen.\nWirkbereiche der Desinfektionsmittel: Bakterizid = Bakterien (ohne Sporen und Mykobakterien) (z. B. MRSA, MRGN, VRE); Levurozid / fungizid = Hefepilze bzw. alle Pilze (z. B. Candida); Tuberkulozid / mykobakterizid = Tuberkulose-Erreger bzw. alle Mykobakterien (Offene Tuberkulose); Begrenzt viruzid = Nur behüllte Viren (z. B. Influenza, SARS-CoV-2, HBV, HCV, HIV, Herpes); Begrenzt viruzid PLUS = Behüllte Viren plus Adeno-, Noro- und Rotaviren (Noroviren, Rotaviren); Viruzid = Alle Viren, auch unbehüllte (z. B. Hepatitis A, Polio); Sporizid = Bakteriensporen (C. difficile).", "pflegeschwerpunkt": "Türschild: Hinweis an der Tür ohne Diagnose oder Erregernamen (Datenschutz, Schweigepflicht), z. B. „Bitte vor Betreten im Stationszimmer melden“ oder ein Symbol nach Hausstandard.\nInformation: Isolierung in Kurve, Pflegedokumentation, Übergabe und bei Verlegung/Entlassung weitergeben. Weiterbehandelnde (Funktionsabteilungen, Rettungsdienst, Pflegeheim) informieren.\nVorraum / vor der Tür: PSA, Händedesinfektionsmittel und Abwurf griffbereit. Bei aerogenen Erregern Schleuse nutzen, beide Türen nie gleichzeitig öffnen.\nMaterial im Zimmer: Nur so viel wie nötig – Überschuss muss bei Entlassung oft verworfen werden. Stethoskop, Blutdruckmanschette, Thermometer, Staubinde patientenbezogen im Zimmer lassen.\nArbeitsablauf: Tätigkeiten bündeln, alles vorher richten. Isolierte möglichst zuletzt versorgen (Ausnahme: Schutzisolierung – zuerst).\nWäsche: Im Zimmer in den Wäschesack, nicht schütteln, nicht auf den Boden. Feuchte Wäsche in einen flüssigkeitsdichten Sack. Kennzeichnung nach Hygieneplan.\nAbfall: Meist als normaler Krankenhausabfall (AS 18 01 04) im Zimmer entsorgen. Nur bei bestimmten Erregern bzw. Materialien als gefährlicher Abfall (AS 18 01 03*) – Hygieneplan.\nGeschirr: Normale maschinelle, thermische Aufbereitung reicht. Kein Einmalgeschirr nötig.\nSteckbecken & Toilette: Patientenbezogen, Aufbereitung im Steckbeckenspüler (thermisch). Bei Durchfall eigene Toilette.\nReinigung: Mindestens täglich Wischdesinfektion der patientennahen Flächen (Nachttisch, Bettgitter, Klingel, Türklinke) mit geeignetem Wirkbereich.\nBesuch: Besucher anleiten: Händedesinfektion beim Betreten und Verlassen, Schutzkleidung nach Hygieneplan, nicht auf das Bett setzen, keine anderen Zimmer besuchen.\nAufhebung: Nur auf ärztliche Anordnung bzw. nach den Kriterien im Hygieneplan. Danach Schlussdesinfektion: alle Flächen und Geräte, Wechsel von Vorhängen, Einmalmaterial verwerfen, Bett aufbereiten.\nTransport: 1. Ist der Transport wirklich nötig? Kann die Untersuchung im Zimmer stattfinden?. 2. Zielbereich und Transportdienst vorher informieren – möglichst Termin am Ende des Programms. 3. Patient: frische Kleidung bzw. frisches Laken, Hände desinfizieren, Wunden/Drainagen/Stoma sicher abdecken. 4. Bei Tröpfchen- oder aerogener Übertragung trägt der Patient einen MNS (wenn tolerierbar). 5. Begleitpersonal trägt PSA nur bei direktem Kontakt – Kittel/Handschuhe nicht über den Flur tragen. 6. Kontakt zu anderen Patienten vermeiden, Wartebereiche meiden. 7. Danach Bett/Rollstuhl/Trage und alle Kontaktflächen desinfizieren.", "klinische_relevanz": "Studien zeigen bei isolierten Menschen häufiger Angst, Niedergeschlagenheit, Einsamkeit und das Gefühl, „gefährlich“ zu sein. Isolierte Patienten erhalten oft weniger Besuche vom Team – und Komplikationen (z. B. Stürze, Dekubitus) werden später bemerkt. Ältere Menschen und Menschen mit Demenz reagieren häufiger mit Delir oder Rückzug.\nWas hilft: Erklären, warum isoliert wird, wie lange voraussichtlich und was die Person selbst tun kann; Sich mit Namen und Funktion vorstellen – hinter Maske und Brille ist man kaum zu erkennen; Bewusst Zeit nehmen, Blickkontakt, ruhiger Tonfall – nicht nur „rein, raus“; Klingel, Telefon, Getränke, Brille, Fernbedienung in Reichweite; Tagesstruktur, Uhr, Kalender; Kontakt zu Angehörigen ermöglichen (z. B. Telefon, Video); Keine abwertenden Begriffe („der Keimpatient“, „MRSA-Zimmer“) – auch nicht im Stationszimmer; Auf Stimmung, Schlaf, Orientierung und Appetit achten und dokumentieren.\nMeldepflicht: § 6 IfSG – Ärztin/Arzt meldet – Namentlich u. a. Verdacht, Erkrankung oder Tod bei: Masern, Mumps, Röteln, Windpocken, Pertussis, Meningokokken-Meningitis/-Sepsis, behandlungsbedürftige Tuberkulose, schwere C.-difficile-Infektion. Außerdem akute infektiöse Gastroenteritis bei Beschäftigten in Lebensmittelbereichen oder bei ≥ 2 Fällen mit vermutetem Zusammenhang. § 7 IfSG – Labor meldet – Erregernachweise, z. B. MRSA in Blut oder Liquor, Carbapenem-resistente Enterobacterales und Acinetobacter (Infektion oder Kolonisation), Noroviren, Rotaviren, Influenza. § 6 Abs. 3 IfSG – Ausbruch – Gehäuftes Auftreten nosokomialer Infektionen mit wahrscheinlichem Zusammenhang wird nichtnamentlich dem Gesundheitsamt gemeldet – über Hygienefachpersonal bzw. ärztliche Leitung.", "pruefungswissen": "Isolierung nach Übertragungsweg: Kontakt (Kittel + Handschuhe), Tröpfchen (MNS), Luft (FFP2, Tür zu). PSA anlegen: Hände desinfizieren, Kittel, Maske, Brille, Hände desinfizieren, Handschuhe. Ablegen: Handschuhe zuerst, dann Hände desinfizieren, Kittel, Brille, Maske (bei Luftübertragung erst draußen), Hände desinfizieren. Bei C. difficile Hände zusätzlich waschen, bei Noroviren mindestens „begrenzt viruzid PLUS“. Türschild ohne Diagnose.", "merksatz": "Der Übertragungsweg bestimmt die Isolierung – Basishygiene gilt immer, Handschuhe ersetzen nie die Händedesinfektion.", "haeufige_pruefungsfrage": "Welche Isolierungsart brauchst du bei offener Lungentuberkulose?", "mcq": [{"frage": "Welche Isolierungsart brauchst du bei offener Lungentuberkulose?", "optionen": ["Kontaktisolierung", "Tröpfchenisolierung", "Isolierung bei aerogener Übertragung (Luft)", "Keine"], "richtig": 2, "erklaerung": "Tuberkulose wird über Tröpfchenkerne in der Luft übertragen."}, {"frage": "Warum steht auf dem Türschild kein Erregername?", "optionen": ["Weil der Platz fehlt", "Datenschutz und Schweigepflicht – und um Stigmatisierung zu vermeiden", "Weil es keine Rolle spielt", "Damit Besucher raten"], "richtig": 1, "erklaerung": "Diagnosen dürfen Unbefugte nicht erkennen (§ 203 StGB, DSGVO)."}, {"frage": "Was ziehst du beim Ablegen der PSA zuerst aus?", "optionen": ["Maske", "Kittel", "Handschuhe", "Schutzbrille"], "richtig": 2, "erklaerung": "Handschuhe sind am stärksten kontaminiert – zuerst ausziehen, dann Hände desinfizieren."}, {"frage": "Welcher Wirkbereich reicht bei Noroviren?", "optionen": ["Bakterizid", "Begrenzt viruzid", "Mindestens begrenzt viruzid PLUS", "Levurozid"], "richtig": 2, "erklaerung": "Noroviren sind unbehüllt – „begrenzt viruzid“ reicht nicht."}, {"frage": "Was unterscheidet eine FFP2-Maske von einem MNS?", "optionen": ["Nichts", "FFP2 ist Atemschutz und schützt bei dichtem Sitz die Trägerin vor Partikeln; der MNS schützt vor allem andere", "Der MNS filtert mehr", "FFP2 ist nur für Patienten"], "richtig": 1, "erklaerung": "MNS = Fremdschutz und Spritzschutz, FFP2 = Atemschutz (Eigenschutz)."}, {"frage": "Bei Masern dürfen ins Zimmer …", "optionen": ["alle mit FFP2", "nur Personal mit nachgewiesener Immunität", "nur Ärztinnen und Ärzte", "nur Schwangere"], "richtig": 1, "erklaerung": "Masern sind hochansteckend – nur immunes Personal (Masernschutz, § 20 IfSG)."}, {"frage": "Wann wird die Isolierung bei Meningokokken aufgehoben?", "optionen": ["Nach 7 Tagen", "24 Stunden nach Beginn der wirksamen Antibiotikatherapie", "Nach Entlassung", "Wenn das Fieber weg ist"], "richtig": 1, "erklaerung": "Nach 24 Stunden wirksamer Therapie ist die Person nicht mehr ansteckend."}, {"frage": "Was ist eine Kohortenisolierung?", "optionen": ["Jeder Patient im eigenen Zimmer", "Mehrere Patienten mit demselben Erreger in einem Zimmer", "Isolierung nur nachts", "Isolierung im Flur"], "richtig": 1, "erklaerung": "Kohorte = gleicher Erreger, gleiches Resistenzmuster, gemeinsames Zimmer."}, {"frage": "Welche Patienten versorgst du bei einer Schutzisolierung zuerst?", "optionen": ["Die schutzisolierte Person", "Die infektiösen Patienten", "Egal", "Den, der klingelt"], "richtig": 0, "erklaerung": "Abwehrgeschwächte zuerst, infektiöse Patienten zuletzt."}, {"frage": "Was gilt für Hepatitis B im Krankenhaus?", "optionen": ["Strikte Einzelzimmerisolierung", "Keine Isolierung – Basishygiene, sichere Instrumente, Impfung", "FFP2 für alle", "Kohorte mit HIV-Patienten"], "richtig": 1, "erklaerung": "Übertragung über Blut – Isolierung bringt keinen zusätzlichen Schutz."}, {"frage": "Ein isolierter Patient muss zum CT. Was ist am wichtigsten?", "optionen": ["Er trägt Kittel und Handschuhe", "Den Zielbereich vorher informieren", "Schnell durch den Flur", "Gar nicht transportieren"], "richtig": 1, "erklaerung": "So kann sich das CT vorbereiten (Termin am Ende, Desinfektion danach)."}, {"frage": "Was wirkt gegen Milben bei Skabies am sichersten?", "optionen": ["Alkoholische Händedesinfektion", "Handschuhe und langärmeliger Kittel bei Körperkontakt", "Nur Abstand", "Ein MNS"], "richtig": 1, "erklaerung": "Händedesinfektion tötet Milben nicht sicher ab – Barriereschutz ist entscheidend."}, {"frage": "Was bedeutet 4MRGN?", "optionen": ["Resistent gegen 4 von 4 Antibiotikagruppen (inkl. Carbapeneme)", "4 Patienten mit MRGN", "Viertes Screening", "Resistent gegen 4 Desinfektionsmittel"], "richtig": 0, "erklaerung": "Resistent gegen Acylureidopenicilline, Cephalosporine der 3./4. Generation, Fluorchinolone und Carbapeneme."}, {"frage": "Wie lange wirkt die hygienische Händedesinfektion meist ein?", "optionen": ["5 Sekunden", "30 Sekunden", "3 Minuten", "Bis die Hände trocken sind, egal wie lange"], "richtig": 1, "erklaerung": "Meist 30 Sekunden (Herstellerangabe beachten), die Hände bleiben dabei feucht."}, {"frage": "Was hilft gegen die psychische Belastung durch Isolierung?", "optionen": ["Möglichst selten ins Zimmer gehen", "Erklären, vorstellen, bewusst Zeit nehmen, Klingel in Reichweite", "Die Tür immer offen lassen, auch bei TB", "Nicht über die Isolierung sprechen"], "richtig": 1, "erklaerung": "Isolierte Menschen fühlen sich oft allein und stigmatisiert – Kommunikation und Zeit helfen."}], "pdf": "isolation", "pdf_titel": "Isolationsmanagement"}$j$::jsonb,
  quelle = 'KRINKO-Empfehlungen (2012–2019), RKI-Ratgeber, TRBA 250, IfSG',
  stand = now(),
  geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie & Intensivmedizin',
  geprueft_am = now(),
  aktiv = true
where slug = 'isolationsmassnahmen';
-- Kontrolle: select slug, titel, length(daten::text) from public.lerninhalte where slug = 'isolationsmassnahmen';
